   "module": "changshi",
   "q": "下列语句按出现时间先后排序正确的是：①劳心者治人，劳力者治于人②少年富则国富，少年强则国强③苟全性命于乱世，不求闻达于诸侯④业精于勤，荒于嬉；行成于思，毁于随",
