   "explain": "①出自《孟子》，为战国时期；②出自梁启超《少年中国说》，为民国时期；③出自诸葛亮的《出师表》， 为三国时期；④出自韩愈的《进学解》，为唐朝时期。故时间顺序为①③④②。 故正确答案为C。",
