   "explain": "A 项：怀素的狂草被形容为“挥毫掣电，随手万变”。B 项：原诗为：今闻东楚人，结网为书圃。池墨泼飞 云，紫毫挥广宇。风流与我逢，狂草竞龙舞。一舞醉三回，消愁极千古。描写的对象亦是狂草。C 项：湖光秋月 两相和，潭面无风镜未磨，出自唐朝刘禹锡的《望洞庭》。意译为：洞庭湖的水光与秋月交相融和，水面波平浪 静就好像铜镜未磨。因此描述的对象为洞庭湖。D 项：李白曾在一首诗里对某一书法作品称赞道：“飘风骤雨",
