   "module": "changshi",
   "q": "话说当时住持真人对洪太尉说道：“太尉不知，此殿中当初是祖老天师洞玄真人传下法符，嘱咐道：‘此殿内镇锁着三十六员天罡星，七十二座地煞星，共是一百单八个魔君在里面，上立石碑，凿着龙章凤篆天符，镇住在此，若还放他出世，必恼下方生灵。’如今太尉放他走了，怎生是好？”关于这段文字所属著作，下列说法正确的是：",
