   "module": "shuliang",
   "q": "把12 棵同样的松树和6 棵同样的柏树种植在道路两侧，每侧种植9 棵，要求每侧的柏树数量相等且不相邻，且道路起点和终点处两侧种植的都必须是松树。问有多少种不同的种植方法：",
